-- =====================================================================
-- e-MART catalogue seed, built from the Flipkart sample dataset.
--
-- Replaces ONLY the catalogue. users / address / emart_card / cart are
-- left untouched, so existing accounts survive. cart_items and wishlist
-- are cleared because both carry a foreign key to prod_id.
--
-- Every price is a clean round rupee value. No 299, no 234.23.
-- =====================================================================

USE emart;

SET FOREIGN_KEY_CHECKS = 0;
TRUNCATE TABLE wishlist;
TRUNCATE TABLE cart_items;
TRUNCATE TABLE prod_dtl_master;
TRUNCATE TABLE config_master;
TRUNCATE TABLE product_image;
TRUNCATE TABLE product_master;
TRUNCATE TABLE category_master;
SET FOREIGN_KEY_CHECKS = 1;

